def solve_cvrp(instance):
    # deterministic constructive + simple repair + local-improvement CVRP solver
    # Assumes instance with keys:
    # - 'customer_count' -> N
    # - 'demands' -> list length N (customer i demand at index i-1)
    # - 'capacity' -> C
    # - optional 'distances' as either a dict {(i,j):d} or a 2D list-like matrix
    def get_n():
        return instance['customer_count']

    def get_demand(i):
        return instance['demands'][i-1]

    def get_distance(i, j):
        dist = instance.get('distances', None)
        if dist is not None:
            try:
                if isinstance(dist, dict):
                    if (i, j) in dist:
                        return dist[(i, j)]
                    if (j, i) in dist:
                        return dist[(j, i)]
                if isinstance(dist, list):
                    # assume 1-based indices, convert to 0-based
                    if 0 <= i-1 < len(dist) and 0 <= j-1 < len(dist):
                        return dist[i-1][j-1]
            except Exception:
                pass
        # fallback simple heuristic
        if i == j:
            return 0
        if i == 0 or j == 0:
            # depot distance to customer
            t = i if i != 0 else j
            return t
        return abs(i - j)

    N = get_n()
    if N <= 0:
        return []

    C = instance['capacity']

    # Deterministic ordering: sort by (distance from depot + 0.5 * demand)
    scores = []
    for c in range(1, N+1):
        d_dep = get_distance(0, c)
        s = float(d_dep) + 0.5 * get_demand(c)
        scores.append((s, c))
    scores.sort()

    # Construct routes by filling to capacity
    routes = []
    current = []
    load = 0
    for _, cust in scores:
        m = get_demand(cust)
        if m > C:
            # If a single demand exceeds capacity, still place in its own route (will be infeasible in practice but keeps deterministic behavior)
            if current:
                routes.append(current)
            routes.append([cust])
            current = []
            load = 0
            continue
        if load + m <= C:
            current.append(cust)
            load += m
        else:
            if current:
                routes.append(current)
            current = [cust]
            load = m
    if current:
        routes.append(current)

    # Local improvement: within-route adjacent swaps if beneficial
    def route_cost(route):
        if not route:
            return 0
        cost = 0
        prev = 0  # depot
        for c in route:
            cost += get_distance(prev, c)
            prev = c
        return cost

    def improve_route(route):
        if len(route) <= 1:
            return route
        best = list(route)
        best_cost = route_cost(best)
        # try adjacent swaps deterministically
        for i in range(len(route) - 1):
